\begin{tikzpicture}[font=\sffamily, line cap=round, thick]
  % beakers
  \draw (0.5,4.5) -- (0.5,0.5) -- (3.5,0.5) -- (3.5,4.5);
  \draw (5.5,4.5) -- (5.5,0.5) -- (8.5,0.5) -- (8.5,4.5);

  % solutions
  \dotregion{0.5}{0.5}{3.5}{3.0}
  \dotregion{5.5}{0.5}{8.5}{3.0}
  \draw (0.5,3.0) -- (3.5,3.0);
  \draw (5.5,3.0) -- (8.5,3.0);

  % electrodes
  \fill[gray!60] (1.9,1.2) rectangle (2.2,5.5);
  \draw (1.9,1.2) rectangle (2.2,5.5);
  \fill[gray!60] (6.9,1.2) rectangle (7.2,5.5);
  \draw (6.9,1.2) rectangle (7.2,5.5);

  % external circuit with voltmeter
  \draw (2.05,5.5) -- (2.05,7.0) -- (3.9,7.0);
  \draw (4.6,7.0) -- (7.05,7.0) -- (7.05,5.5);
  \draw (4.25,7.0) circle (0.35);
  \node at (4.25,7.0) {V};

  % salt bridge
  \draw (3.5,2.2) .. controls (3.7,5.6) and (5.3,5.6) .. (5.5,2.2);
  \node[font=\sffamily\small] at (4.5,4.9) {salt bridge};

  % electrode labels
  \draw (1.9,4.9) -- (-0.2,4.9);
  \node[left] at (-0.2,4.9) {Zn};
  \draw (7.2,4.9) -- (9.2,4.9);
  \node[right] at (9.2,4.9) {Cu};

  % solution labels
  \node at (2.0,-0.4) {Zn$^{2+}$(aq)};
  \node at (7.0,-0.4) {Cu$^{2+}$(aq)};

  % caption
  \node at (4.5,-1.3) {\textbf{Fig. 6.1}};
\end{tikzpicture}
